echo "מעדכן את pubspec.yaml (מוסיף את קבצי התמונה כ-assets)..."
python3 << 'PUBSPEC_PATCH_EOF'
import re
path = 'pubspec.yaml'
asset_paths = ['assets/vehicle_backgrounds/sunset_mountains.jpg', 'assets/vehicle_backgrounds/red_coast_sunset.jpg', 'assets/vehicle_backgrounds/blue_night_mountain.jpg', 'assets/vehicle_backgrounds/yellow_palms_sunset.jpg', 'assets/vehicle_backgrounds/city_dusk_road.jpg', 'assets/vehicle_backgrounds/white_coast_sunset.jpg']
with open(path, encoding='utf-8') as f:
    content = f.read()
lines = content.split(chr(10))
flutter_idx = None
for i, line in enumerate(lines):
    if line.rstrip() == 'flutter:':
        flutter_idx = i
        break
added, skipped = [], []
if flutter_idx is None:
    lines.append('')
    lines.append('flutter:')
    lines.append('  assets:')
    for p in asset_paths:
        lines.append('    - ' + p)
    added = list(asset_paths)
else:
    end_idx = len(lines)
    for j in range(flutter_idx+1, len(lines)):
        line = lines[j]
        if line.strip() == '':
            continue
        if not line.startswith(' ') and not line.startswith(chr(9)):
            end_idx = j
            break
    block = lines[flutter_idx:end_idx]
    assets_idx = None
    for k, line in enumerate(block):
        if line.strip() == 'assets:':
            assets_idx = k
            break
    if assets_idx is None:
        insertion = ['  assets:'] + ['    - ' + p for p in asset_paths]
        block = block[:1] + insertion + block[1:]
        added = list(asset_paths)
    else:
        assets_indent = len(block[assets_idx]) - len(block[assets_idx].lstrip())
        list_end = len(block)
        for k in range(assets_idx+1, len(block)):
            line = block[k]
            if line.strip() == '':
                continue
            indent = len(line) - len(line.lstrip())
            if indent <= assets_indent:
                list_end = k
                break
        existing_list_lines = block[assets_idx+1:list_end]
        existing_paths = set()
        for line in existing_list_lines:
            m = re.match(r'\s*-\s*(.+)', line)
            if m:
                existing_paths.add(m.group(1).strip())
        new_lines = []
        for p in asset_paths:
            if p in existing_paths:
                skipped.append(p)
            else:
                new_lines.append('    - ' + p)
                added.append(p)
        block = block[:list_end] + new_lines + block[list_end:]
    lines = lines[:flutter_idx] + block + lines[end_idx:]
content = chr(10).join(lines)
with open(path, 'w', encoding='utf-8') as f:
    f.write(content)
for p in added:
    print(f'  {p} נוסף ל-pubspec.yaml.')
for p in skipped:
    print(f'  {p} כבר קיים ב-pubspec.yaml - מדלג.')
PUBSPEC_PATCH_EOF

